export const ComplyTestControllerRequestSchema: z.ZodObject<Record<string, z.ZodType>, any> = z.object({
    adcp_version: z.string().optional(),
    adcp_major_version: z.number().optional(),
    scenario: z.string(),
    params: z.object({
        creative_id: z.string().optional(),
        account_id: z.string().optional(),
        media_buy_id: z.string().optional(),
        session_id: z.string().optional(),
        product_id: z.string().optional(),
        proposal_id: z.string().min(1).optional(),
        pricing_option_id: z.string().optional(),
        plan_id: z.string().optional(),
        rights_id: z.string().optional(),
        fixture: z.object({}).passthrough().optional(),
        operation: z.union([z.literal("seed_inaccessible_item"), z.literal("query_eligibility"), z.literal("advance_time"), z.literal("recreate_catalog"), z.literal("prepare"), z.literal("expire_proposal")]).optional(),
        catalog_id: z.string().min(1).max(255).optional(),
        catalog_generation: z.string().min(1).max(255).optional(),
        item_id: z.string().min(1).max(255).optional(),
        target_time: z.iso.datetime().optional(),
        status: z.string().optional(),
        rejection_reason: z.string().optional(),
        purge_kind: z.union([z.literal("soft"), z.literal("hard")]).optional(),
        reason_code: CreativeEventReasonCodeSchema.optional(),
        reason_detail: z.string().optional(),
        termination_reason: z.string().optional(),
        impressions: z.number().min(0).optional(),
        clicks: z.number().min(0).optional(),
        conversions: z.number().min(0).optional(),
        delivery_date: z.iso.date().optional(),
        conversion_value: z.number().min(0).optional(),
        commissionable_value: z.number().min(0).optional(),
        reported_spend: z.object({
            amount: z.number().min(0),
            currency: z.string().regex(/^[A-Z]{3}$/)
        }).passthrough().optional(),
        reach: z.number().min(0).optional(),
        frequency: z.number().min(0).optional(),
        reach_window: z.object({
            kind: z.union([z.literal("cumulative"), z.literal("period"), z.literal("rolling")]),
            period: DurationSchema.optional()
        }).passthrough().optional(),
        viewability: z.object({
            measurable_impressions: z.number().min(0).optional(),
            viewable_impressions: z.number().min(0).optional(),
            viewable_rate: z.number().min(0).max(1).optional(),
            viewed_seconds: z.number().min(0).optional(),
            standard: ViewabilityStandardSchema.optional()
        }).passthrough().optional(),
        vendor_metric_values: z.array(VendorMetricValueSchema).optional(),
        vendor_metric_values_by_package: z.record(z.string(), z.array(VendorMetricValueSchema)).optional(),
        not_yet_measurable_vendor_metrics: z.array(z.object({
            vendor: BrandReferenceSchema,
            metric_id: VendorMetricIDSchema
        }).passthrough()).optional(),
        not_yet_measurable_vendor_metrics_by_package: z.record(z.string(), z.array(z.object({
                vendor: BrandReferenceSchema,
                metric_id: VendorMetricIDSchema
            }).passthrough())).optional(),
        spend_percentage: z.number().min(0).max(100).optional(),
        arm: z.union([z.literal("submitted"), z.literal("input-required"), z.literal("rejected")]).optional(),
        task_id: z.string().max(128).optional(),
        message: z.string().max(2000).optional(),
        reason: z.string().min(1).max(2000).optional(),
        suggestions: z.array(z.string()).optional(),
        format_id: z.string().optional(),
        vendor: BrandReferenceSchema.optional(),
        metrics: z.array(z.object({
            metric_id: VendorMetricIDSchema
        }).passthrough()).optional(),
        tool: z.string().optional(),
        upstream_name: z.string().optional(),
        result: ComplianceTaskCompletionDataSchema.optional(),
        since_timestamp: z.iso.datetime().optional(),
        endpoint_pattern: z.string().optional(),
        limit: z.number().min(1).max(1000).optional(),
        attestation_mode: z.union([z.literal("raw"), z.literal("digest")]).optional(),
        identifier_value_digests: z.array(z.string()).optional()
    }).passthrough().optional(),
    context: ContextObjectSchema.optional(),
    ext: ExtensionObjectSchema.optional(),
    account: z.object({
        sandbox: z.literal(true)
    }).passthrough()
}).passthrough();

